#[test]
fn test_a_label_beside_a_table_of_fields_comes_before_it() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tb: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // P12.7 (smoke A N4): the 1120's column of boxes and line numbers (x 468 to 576, y 325.9 to 372) stands beside the labels of its rows, which end at x 338: a field comes after its label. A line to the left of
    // the table that begins in its height is written before it; one below it, or to the right of its left edge, is not (the table goes first, as ever).
    tb_add(tb, 1, 46800, 32590, 57620, 37200, 0, 1000, 3, 3, 0, 0);
    bl_line(wd, ln, et, &crate::testport::text_blob("13 Salaries and wages")[..], 1, 5590, 32590, 800);
    bl_line(wd, ln, et, &crate::testport::text_blob("Repairs")[..], 1, 5590, 36000, 800);
    bl_line(wd, ln, et, &crate::testport::text_blob("later text")[..], 1, 5590, 38000, 800);
    bl_line(wd, ln, et, &crate::testport::text_blob("right of it")[..], 1, 50000, 32590, 800);
    crate::testport::assert_eq(bl_due(tb, ln, 0), 0, "a label at the table's top, to its left: it comes first");
    crate::testport::assert_eq(bl_due(tb, ln, 1), 0, "so does the label of its fourth row");
    crate::testport::assert_eq(bl_due(tb, ln, 2), 1, "a line under the table: the table goes first");
    crate::testport::assert_eq(bl_due(tb, ln, 3), 1, "a line at its top but to its right: the table goes first");
}
