    bl_body(wd, ln, et, 2);
    bl_model(wd, ln, et, 2, nodes, attrs, regions, text, pages);
    crate::testport::assert_eq(bl_yes(bl_find(nodes, nk_caption(), 0)), 0, "a running header and footer are no captions");
